is_balanced:
def is_balanced(s):
    stack = []
    brackets = {'(': ')', '[': ']', '{': '}'}
    for char in s:
        if char in brackets:
            stack.append(char)
        elif char in brackets.values():
            if not stack or brackets[stack.pop()] != char:
                return False
    return not stack

two_sum:
def two_sum(nums, target):
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], i]
        num_to_index[num] = i
    return []

roman_to_int:
def roman_to_int(s):
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

merge_intervals:
def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals based on the start time
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]

    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping intervals, merge them
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)

    return merged

longest_unique:
def longest_unique(s):
    char_map = {}
    max_length = 0
    start = 0

    for end, char in enumerate(s):
        if char in char_map and char_map[char] >= start:
            start = char_map[char] + 1
        char_map[char] = end
        max_length = max(max_length, end - start + 1)

    return max_length

spiral_order:
def spiral_order(matrix):
    if not matrix:
        return []

    rows, cols = len(matrix), len(matrix[0])
    result = []
    top, bottom, left, right = 0, rows - 1, 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for i in range(left, right + 1):
            result.append(matrix[top][i])
        top += 1

        if top > bottom:
            break

        # Traverse from top to bottom
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
        right -= 1

        if left > right:
            break

        # Traverse from right to left
        for i in range(right, left - 1, -1):
            result.append(matrix[bottom][i])
        bottom -= 1

        if top > bottom:
            break

        # Traverse from bottom to top
        for i in range(bottom, top - 1, -1):
            result.append(matrix[i][left])
        left += 1

    return result

word_break:
def word_break(s, word_dict):
    word_set = set(word_dict)
    dp = [False] * (len(s) + 1)
    dp[0] = True

    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break
    return dp[len(s)]

coin_change:
def coin_change(coins, amount):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

lru_cache:
class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key):
        if key in self.cache:
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]
        return -1

    def put(self, key, value):
        if key in self.cache:
            self.order.remove(key)
        elif len(self.order) >= self.capacity:
            lru_key = self.order.pop(0)
            del self.cache[lru_key]
        self.order.append(key)
        self.cache[key] = value

edit_distance:
def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]

trap_rain:
def trap_rain(height):
    if not height:
        return 0
    left, right = 0, len(height) - 1
    left_max, right_max = height[left], height[right]
    total = 0
    while left < right:
        if left_max < right_max:
            left += 1
            left_max = max(left_max, height[left])
            total += left_max - height[left]
        else:
            right -= 1
            right_max = max(right_max, height[right])
            total += right_max - height[right]
    return total

regex_match:
def regex_match(s, p):
    memo = {}

    def match(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if j == len(p):
            return i == len(s)
        # Check if the current pattern character is a '*'
        if j + 1 < len(p) and p[j + 1] == '*':
            # Check for zero or more occurrences
            if p[j] == '.' or p[j] == s[i]:
                # Match zero occurrences
                if match(i, j + 2):
                    memo[(i, j)] = True
                    return True
                # Match one or more occurrences
                if i < len(s) and (p[j] == '.' or p[j] == s[i]) and match(i + 1, j):
                    memo[(i, j)] = True
                    return True
            memo[(i, j)] = False
            return False
        # Check if current pattern character matches
        if p[j] == '.' or p[j] == s[i]:
            memo[(i, j)] = match(i + 1, j + 1)
            return memo[(i, j)]
        memo[(i, j)] = False
        return False

    return match(0, 0)

n_queens:
def n_queens(n):
    def backtrack(row, cols, diag, anti_diag):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            current_diag = row - col
            current_anti_diag = row + col
            if cols[col] or diag[current_diag] or anti_diag[current_anti_diag]:
                continue
            cols[col] = True
            diag[current_diag] = True
            anti_diag[current_anti_diag] = True
            count += backtrack(row + 1, cols, diag, anti_diag)
            cols[col] = False
            diag[current_diag] = False
            anti_diag[current_anti_diag] = False
        return count

    return backtrack(0, [False] * n, [False] * (2 * n), [False] * (2 * n))

calculate:
def calculate(s: str) -> int:
    s = s.replace(' ', '')
    num_stack = []
    op_stack = []
    i = 0
    n = len(s)

    while i < n:
        if s[i].isdigit():
            num = 0
            while i < n and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            num_stack.append(num)
        else:
            if not op_stack or precedence(s[i]) > precedence(op_stack[-1]):
                op_stack.append(s[i])
            else:
                while op_stack and precedence(op_stack[-1]) >= precedence(s[i]):
                    b = num_stack.pop()
                    a = num_stack.pop()
                    op = op_stack.pop()
                    if op == '+':
                        num_stack.append(a + b)
                    elif op == '-':
                        num_stack.append(a - b)
                    elif op == '*':
                        num_stack.append(a * b)
                    elif op == '/':
                        if b == 0:
                            raise ZeroDivisionError("Division by zero")
                        num_stack.append(a // b if a * b >= 0 else -(-a // b))
                op_stack.append(s[i])
            i += 1

    while op_stack:
        b = num_stack.pop()
        a = num_stack.pop()
        op = op_stack.pop()
        if op == '+':
            num_stack.append(a + b)
        elif op == '-':
            num_stack.append(a - b)
        elif op == '*':
            num_stack.append(a * b)
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            num_stack.append(a // b if a * b >= 0 else -(-a // b))

    return num_stack[0]

def precedence(op: str) -> int:
    if op in ('+', '-'):
        return 1
    elif op in ('*', '/'):
        return 2
    return 0

lis_length:
def lis_length(nums):
    n = len(nums)
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

min_path_sum:
def min_path_sum(grid):
    m, n = len(grid), len(grid[0])
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            elif i == 0:
                grid[i][j] += grid[i][j-1]
            elif j == 0:
                grid[i][j] += grid[i-1][j]
            else:
                grid[i][j] += min(grid[i-1][j], grid[i][j-1])
    return grid[-1][-1]

decode_ways:
def decode_ways(s):
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # empty string has one way to decode
    dp[1] = 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        if s[i-1] != '0':
            dp[i] += dp[i-1]
        if 10 <= int(s[i-2:i]) <= 26:
            dp[i] += dp[i-2]

    return dp[n]
